import{z as l,x as r,o as B,c as p,q as i,j as s,D as a,d as o,s as t,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"家庭组合与参与之谜","description":"","frontmatter":{"title":"家庭组合与参与之谜","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/household-portfolio-participation.md","filePath":"econ/household-portfolio-participation.md","lastUpdated":1791063341000}'),d={name:"econ/household-portfolio-participation.md"};function C(m,E,h,c,F,u){const A=r("Mermaid");return B(),p("div",null,[E[2]||(E[2]=i('<h1 id="家庭组合与参与之谜" tabindex="-1">家庭组合与参与之谜 <a class="header-anchor" href="#家庭组合与参与之谜" aria-label="Permalink to &quot;家庭组合与参与之谜&quot;">​</a></h1><div class="epigraph"><p>有限参与不是「有人没听说过股票」的注脚：它改写谁的消费进入定价核，也改写股权溢价该向谁校准。</p><footer>—— Mankiw and Zeldes, The Consumption of Stockholders and Nonstockholders, JFE 1991；Haliassos and Bertaut, EJ 1995</footer></div><p><a href="/econ/housing-asset-consumption">上一课</a>把净值绑在房子上。本课缺口是金融风险资产：标准两基金分离预测，只要风险厌恶有限、股权有正溢价，人人持有市场组合的某一杠杆。数据里大量家庭股票持有为零。不重写 <a href="/econ/capm-theory">CAPM</a> 的均衡推导，只问参与的零角点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Merton 连续时间、两基金分离：风险资产份额由夏普与风险厌恶决定，可以为小，但恰好为零需要无限厌恶或零溢价。Haliassos 与 Bertaut（1995）把零持有写成谜。Mankiw 与 Zeldes（1991）比较持股者与非持股者的消费：持股者消费与股市更共变，\\(\\sigma(m)\\) 的微观候选更抖——这是对<a href="/econ/equity-premium-puzzle">股权溢价之谜</a>的参与侧翻译，不重推 HJ 界。Vissing-Jørgensen（2002）强调固定参与成本：小财富下成本吃掉溢价，零持有可以是理性角点。</p><p>缺口是在住房挤出之后，再加一层参与决策，而不是重讲期望效用公理。</p><p><span class="marginnote">Guiso、Haliassos 与 Jappelli 的跨国比较：参与随财富、教育、信任变化。信任与素养是下一课，本课先钉成本和背景风险。</span></p><p><span class="marginnote">数字实例：固定参与成本（开户、研究、跟踪）大约几百美元。若家庭只有 1000 美元可投、股权溢价约 5%，每年多赚约 50 美元，一摊上时间成本就不划算；财富到几万美元时，同一笔成本才被溢价盖过。小财富家庭的零持有可以是一笔算得过来的账。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在缓冲存量加住房的资产负债表上，加一只股权。固定成本（信息、开户、时间）使价值函数在「参与 / 不参与」上离散比较。背景风险（劳动收入、房价）若与股市正相关，挤出股票；若不可保且独立，也可能挤出（谨慎）。卖空限制把负份额关掉，零成为角点。</p>',10)),(B(),s(n,null,{default:a(()=>[t(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEP%5B%22%E4%B8%A4%E5%9F%BA%E9%87%91%3A%20%E4%BB%BD%E9%A2%9D%E5%8F%AF%E4%B8%BA%E5%B0%8F%E4%BD%86%E9%9D%9E%E9%9B%B6%22%5D%20--%3E%20ZERO%5B%22%E8%A7%82%E6%B5%8B%3A%20%E5%A4%A7%E9%87%8F%E9%9B%B6%E6%8C%81%E6%9C%89%22%5D%0A%20%20ZERO%20--%3E%20FC%5B%22%E5%9B%BA%E5%AE%9A%E5%8F%82%E4%B8%8E%E6%88%90%E6%9C%AC%22%5D%0A%20%20ZERO%20--%3E%20BG%5B%22%E8%83%8C%E6%99%AF%E9%A3%8E%E9%99%A9%E4%B8%8E%E4%BD%8F%E6%88%BF%22%5D%0A%20%20ZERO%20--%3E%20EP%5B%22%E6%8C%81%E8%82%A1%E8%80%85%E6%B6%88%E8%B4%B9%E6%9B%B4%E5%85%B1%E5%8F%98%3A%20%E6%BA%A2%E4%BB%B7%E6%A0%A1%E5%87%86%E5%AF%B9%E8%B1%A1%E5%8F%98%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"本课不估计成本美元数。交易协议仍不是对象。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"机制是角点加异质。未参与者的欧拉对股权不成等式，他们的消费不必进市场的 \\(m\\)。代表性主体用总量 \\(c\\) 生成核，把未参与者的平滑消费也算进去，溢价被夸大成「谜」。参与之谜因此既是家庭金融问题，也是资产定价加总问题。住房与劳动收入是背景风险的主要来源；现时偏差和损失厌恶可以再抬高不参与——行为单元再写。",-1)),(B(),s(n,null,{default:a(()=>[t(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A6%81%E4%B8%8D%E8%A6%81%E4%B9%B0%E8%82%A1%E7%A5%A8%EF%BC%9F%22%5D%20--%3E%20G%5B%22%E9%A2%84%E6%9C%9F%E6%94%B6%E7%9B%8A%EF%BC%9A%E8%B4%A2%E5%AF%8C%20%C3%97%20%E8%82%A1%E6%9D%83%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20Q%20--%3E%20C%5B%22%E5%9B%BA%E5%AE%9A%E6%88%90%E6%9C%AC%EF%BC%9A%E5%BC%80%E6%88%B7%E3%80%81%E4%BF%A1%E6%81%AF%E3%80%81%E6%97%B6%E9%97%B4%22%5D%0A%20%20Q%20--%3E%20R%5B%22%E8%83%8C%E6%99%AF%E9%A3%8E%E9%99%A9%EF%BC%9A%E5%8A%B3%E5%8A%A8%E6%94%B6%E5%85%A5%E4%B8%8E%E6%88%BF%E4%BB%B7%E7%9A%84%E6%8C%A4%E5%87%BA%22%5D%0A%20%20C%20--%3E%20T%7B%22%E6%88%90%E6%9C%AC%E4%B8%8E%E6%8C%A4%E5%87%BA%E4%B9%8B%E5%90%8E%E8%BF%98%E5%89%A9%E5%A4%9A%E5%B0%91%E5%87%80%E6%94%B6%E7%9B%8A%EF%BC%9F%22%7D%0A%20%20R%20--%3E%20T%0A%20%20T%20--%3E%7C%22%E5%B0%8F%E8%B4%A2%E5%AF%8C%E5%AE%B6%E5%BA%AD%22%7C%20Z%5B%22%E6%94%B6%E7%9B%8A%E7%9B%96%E4%B8%8D%E4%BD%8F%E6%88%90%E6%9C%AC%EF%BC%9A%E9%9B%B6%E6%8C%81%E6%9C%89%E6%98%AF%E7%90%86%E6%80%A7%E8%A7%92%E7%82%B9%22%5D%0A%20%20T%20--%3E%7C%22%E4%B8%AD%E9%AB%98%E8%B4%A2%E5%AF%8C%E5%AE%B6%E5%BA%AD%22%7C%20P%5B%22%E6%94%B6%E7%9B%8A%E8%B6%B3%E5%A4%9F%EF%BC%9A%E5%8F%82%E4%B8%8E%EF%BC%8C%E6%8C%81%E6%9C%89%E4%B8%80%E4%BB%BD%E7%BB%84%E5%90%88%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=i('<p><span class="marginnote">术语翻译：「角点」就是最优解停在允许范围的边界上（这里是零），而不是落在内部的某个正数。好比空调可以调到任意温度，你却把它整个关掉——不是不会调，而是开着不划算。</span></p><p>与 <a href="/econ/emh">EMH</a> 不冲突：有效是相对信息集的价格陈述；参与是谁愿意持有。未参与不蕴含价格可预测。</p><p>两基金分离来自主干的均值方差或 ICAPM 逻辑，本课不重导。零持有是角点：要么成本吃掉溢价，要么背景风险把有效厌恶抬到参与阈值以上。Mankiw–Zeldes 的含义对溢价之谜是加总的：正确的 \\(c\\) 也许是持股者的 \\(c\\)。补层停在家庭侧；量化栏的 CAPM 实证仍用市场组合，不在此改测量。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>「谜」取决于成本与背景风险能否定量吃掉零持有。年轻、穷、无风险资产也很少的家庭，零持有并不奇怪。真正刺耳的是中高财富、已有缓冲仍不参与。本课把刺耳的区域标出来，定量交给经验文献，不在此校准。</p><p><span class="marginnote">常见误区：初学者容易把不参与一律读成「不懂股票」或「非理性」。模型里零持有可以是精打细算的结果；真正需要解释的，是中高财富、已有缓冲存量、成本明显不构成障碍的家庭仍然持股为零。</span></p><p>后课默认：参与是离散选择；默认选项与素养会移动这个角点，而不必先改变 \\(\\gamma\\)。</p><p>两基金分离几乎禁止零持有；固定成本与背景风险把零写成角点。</p><p>持股者消费更共变，溢价之谜的 \\(c\\) 可能找错了人。未参与不蕴含价格可预测。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两基金分离几乎禁止零持有；数据里零是常态。</li><li>固定成本、住房与劳动收入背景风险给出理性角点。</li><li>持股者消费更共变，溢价之谜的 \\(c\\) 可能找错了人。</li><li>刺耳的是中高财富仍不参与，不是穷人的零持有。</li><li>默认与素养下一课移动这个角点。</li><li>出处：Mankiw and Zeldes, <em>JFE</em> 1991；Haliassos and Bertaut, <em>EJ</em> 1995；Vissing-Jørgensen, 2002。</li></ul>',11))])}const _=l(d,[["render",C]]);export{D as __pageData,_ as default};
